Response* PersonalPageHandler::callback(Request* req) {
    try {
        string user_id = req->getBodyParam("user_id");

        User* user = system->find_user_by_id(user_id);

        string name = user->get_name();
        string profile_path = user->get_profile_path();
        vector<Post*> posts = user->get_posts();
        string page_title;
        string semester;
        string position;

        if (system->who_are_you(user_id) == "student") {
            page_title = "STUDENT PAGE";
            semester = to_string(dynamic_cast<Student*>(user)->get_semester());
            position = "INVALID_VALUE";
        } else if (system->who_are_you(user_id) == "professor") {
            page_title = "PROFESSOR PAGE";
            position = dynamic_cast<Professor*>(user)->get_position();
            semester = "INVALID_VALUE";
        } else if (system->who_are_you(user_id) == "manager") {
            page_title = "UT_ACCOUNT PAGE";
            semester = "INVALID_VALUE";
            position = "INVALID_VALUE";
        }

        Response* res = new Response();
        res->setHeader("Content-Type", "text/html");

        string body;

        body += "<!DOCTYPE html>";
        body += "<html lang=\"en\">";

        body += "<head>";
        body += "  <title>" + page_title + "</title>";
        body += "  <style>";
        body += "    body { text-align: center; font-family: Arial, sans-serif; }";
        body += "    .container { width: 60%; margin: auto; }";
        body += "    .profile { margin-bottom: 20px; }";
        body += "    .profile img { max-width: 100px; max-height: 100px; border-radius: 50%; }";
        body += "    .details { margin-bottom: 20px; }";
        body += "    .details p { margin: 5px 0; }";
        body += "    .post { border: 1px solid #ccc; padding: 10px; margin-bottom: 10px; border-radius: 5px; }";
        body += "    .post img { max-width: 50px; max-height: 50px; vertical-align: middle; margin-right: 10px; }";
        body += "    .post-title { font-weight: bold; display: inline-block; }";
        body += "    .post-message { display: inline-block; vertical-align: middle; }";
        body += "  </style>";
        body += "</head>";

        body += "<body>";
        body += "  <div class=\"container\">";
        body += "    <h1>" + page_title + "</h1>";

        body += "    <div class=\"profile\">";
        body += "      <img src=\"" + profile_path + "\" alt=\"Profile Photo\">";
        body += "    </div>";

        body += "    <div class=\"details\">";
        body += "      <p>Name: " + name + "</p>";
        if (semester != "INVALID_VALUE") body += "      <p>Semester: " + semester + "</p>";
        if (position != "INVALID_VALUE") body += "      <p>Position: " + position + "</p>";
        body += "    </div>";

        for (Post* post : posts) {
            string title = post->title;
            string message = post->message;
            string photo_path = post->photo_path;
            body += "    <div class=\"post\">";
            body += "      <img src=\"" + photo_path + "\" alt=\"Post Photo\">";
            body += "      <span class=\"post-title\">\"" + title + "\"</span>";
            body += "      <span class=\"post-message\">" + message + "</span>";
            body += "    </div>";
        }

        body += "  </div>";
        body += "</body>";

        body += "</html>";
        res->setBody(body);
        return res;
    } catch (Request_Exception& ex) {
        return Response::redirect("/error1");
    } catch (NotFound_Exception& ex) {
        return Response::redirect("/error2");
    }
}
